//!
//! Integration test binaries in this workspace masquerade as the real `codex`
//! CLI so they can dispatch to helper binaries (such as `apply_patch` and
//! `codex-linux-sandbox`) based on `argv0`/`argv1`. Historically each test
//! binary reimplemented the same `#[ctor]` bootstrap logic. This crate
//! centralizes that logic behind [`configure_test_binary_dispatch`].
//!
//! Callers provide a `classify` closure that decides, based on the current
//! executable name and optional first argument, how the process should behave:
//! dispatch through arg0 and exit, skip setup entirely, or install the arg0
//! aliases under a throwaway `CODEX_HOME`.

// This crate is only ever compiled as part of test binaries, so panicking with
// a descriptive message on setup failure is the desired behavior.
#![allow(clippy::expect_used)]

use codex_arg0::Arg0DispatchPaths;
use codex_arg0::Arg0PathEntryGuard;
use codex_arg0::arg0_dispatch;
use std::path::Path;
use tempfile::TempDir;

const CODEX_HOME_ENV_VAR: &str = "CODEX_HOME";

/// Controls what [`configure_test_binary_dispatch`] does for the current
/// process invocation. Returned by the `classify` closure.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TestBinaryDispatchMode {
    /// Dispatch via arg0 (which typically execs a helper CLI and exits) and
    /// return `None`. No aliases are installed for the current process.
    DispatchArg0Only,
    /// Do nothing and return `None`.
    Skip,
    /// Set up a temporary `CODEX_HOME`, install the arg0 dispatch aliases,
    /// restore the previous `CODEX_HOME`, and return a guard.
    InstallAliases,
}

/// Keeps the temporary `CODEX_HOME` directory and the arg0 path entry guard
/// alive for the lifetime of the test binary. Returned by
/// [`configure_test_binary_dispatch`] when aliases are installed.
pub struct TestBinaryDispatchGuard {
    // Held so the temporary CODEX_HOME (which stores the arg0 helper links)
    // outlives the test binary.
    _codex_home: TempDir,
    arg0: Arg0PathEntryGuard,
}

impl TestBinaryDispatchGuard {
    /// Paths to the helper executables that were wired up when the aliases
    /// were installed.
    pub fn paths(&self) -> &Arg0DispatchPaths {
        self.arg0.paths()
    }
}

/// Reads `argv0` and `argv1`, calls `classify(exe_name, argv1)` to determine
/// the dispatch mode, and acts accordingly.
///
/// Intended to be called from a `#[ctor]` static initializer in test binaries,
/// before any test threads are spawned. This matters because installing the
/// aliases mutates the `CODEX_HOME` and `PATH` environment variables, which is
/// only sound while the process is single-threaded.
pub fn configure_test_binary_dispatch<F>(
    codex_home_prefix: &str,
    classify: F,
) -> Option<TestBinaryDispatchGuard>
where
    F: FnOnce(&str, Option<&str>) -> TestBinaryDispatchMode,
{
    let mut args = std::env::args_os();
    let argv0 = args.next().unwrap_or_default();
    let exe_name = Path::new(&argv0)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("");
    let argv1 = args.next();
    let argv1 = argv1.as_deref().and_then(|arg| arg.to_str());

    match classify(exe_name, argv1) {
        TestBinaryDispatchMode::DispatchArg0Only => {
            // arg0_dispatch() inspects argv itself and, for helper aliases,
            // execs the helper and never returns. In the general case it
            // returns a guard that we intentionally discard here.
            let _ = arg0_dispatch();
            None
        }
        TestBinaryDispatchMode::Skip => None,
        TestBinaryDispatchMode::InstallAliases => {
            let codex_home = tempfile::Builder::new()
                .prefix(codex_home_prefix)
                .tempdir()
                .expect("create temporary CODEX_HOME for test binary dispatch");
            let previous_codex_home = std::env::var_os(CODEX_HOME_ENV_VAR);
            // arg0_dispatch() creates helper links under CODEX_HOME/tmp. Point
            // it at a test-owned temp dir so startup never mutates the
            // developer's real ~/.codex.
            //
            // Safety: this runs from a #[ctor] before any test threads start,
            // so mutating the environment is sound.
            unsafe {
                std::env::set_var(CODEX_HOME_ENV_VAR, codex_home.path());
            }

            let arg0 = arg0_dispatch().expect("install arg0 dispatch aliases for test binary");

            // Restore the process environment immediately so later tests
            // observe the same CODEX_HOME state they started with.
            match previous_codex_home.as_ref() {
                Some(value) => unsafe {
                    std::env::set_var(CODEX_HOME_ENV_VAR, value);
                },
                None => unsafe {
                    std::env::remove_var(CODEX_HOME_ENV_VAR);
                },
            }

            Some(TestBinaryDispatchGuard {
                _codex_home: codex_home,
                arg0,
            })
        }
    }
}
